import { describe, it, expect } from 'vitest';
import morning from './morning.json';
import evening from './evening.json';
import sleep from './sleep.json';
import istikhara from './istikhara.json';
import home from './home.json';
import travel from './travel.json';

// Generated by scripts/build-adhkar-data.mjs from Hisn al-Muslim (see docs/credits/adhkar.md).
const sections = { morning, evening, sleep, home, travel };
const ARABIC_LETTER = /[ء-ي]/;
const HARAKA = /[ً-ْ]/;
const ALLOWED_KEYS = new Set(['id', 'arabic', 'repeat', 'virtue', 'source', 'heading']);

const count = (text, phrase) => text.split(phrase).length - 1;

describe.each(Object.entries(sections))('%s adhkar', (name, list) => {
  it('is a non-empty array', () => {
    expect(Array.isArray(list)).toBe(true);
    expect(list.length).toBeGreaterThan(0);
  });

  it('has ids "<section>-NN" in book order, without gaps', () => {
    list.forEach((dhikr, i) => {
      expect(dhikr.id).toBe(`${name}-${String(i + 1).padStart(2, '0')}`);
    });
  });

  it('has only the schema keys { id, arabic, repeat, virtue?, source?, heading? }', () => {
    for (const dhikr of list) {
      for (const key of Object.keys(dhikr)) expect(ALLOWED_KEYS.has(key), `${dhikr.id}.${key}`).toBe(true);
    }
  });

  it('has non-empty Arabic text with tashkeel', () => {
    for (const dhikr of list) {
      expect(typeof dhikr.arabic).toBe('string');
      expect(dhikr.arabic.trim(), dhikr.id).toBe(dhikr.arabic);
      expect(ARABIC_LETTER.test(dhikr.arabic), dhikr.id).toBe(true);
      expect(HARAKA.test(dhikr.arabic), dhikr.id).toBe(true);
    }
  });

  it('has an integer repeat >= 1', () => {
    for (const dhikr of list) {
      expect(Number.isInteger(dhikr.repeat), dhikr.id).toBe(true);
      expect(dhikr.repeat, dhikr.id).toBeGreaterThanOrEqual(1);
    }
  });

  it('has virtue and source, when present, as non-empty Arabic strings', () => {
    for (const dhikr of list) {
      for (const key of ['virtue', 'source', 'heading']) {
        if (!(key in dhikr)) continue;
        expect(typeof dhikr[key], `${dhikr.id}.${key}`).toBe('string');
        expect(dhikr[key].trim().length, `${dhikr.id}.${key}`).toBeGreaterThan(0);
        expect(ARABIC_LETTER.test(dhikr[key]), `${dhikr.id}.${key}`).toBe(true);
      }
    }
  });
});

describe('all sections', () => {
  it('have unique ids across sections', () => {
    const ids = [...morning, ...evening, ...sleep, ...home, ...travel].map((d) => d.id);
    expect(new Set(ids).size).toBe(ids.length);
  });

  it('have the expected number of adhkar (guards against truncation)', () => {
    expect(morning).toHaveLength(23);
    expect(evening).toHaveLength(21);
    expect(sleep).toHaveLength(13);
    expect(home).toHaveLength(3);
    expect(travel).toHaveLength(3);
  });
});

describe('home and travel (hand-entered from Hisn al-Muslim)', () => {
  it('home has a heading on every dhikr: leaving (2) then entering (1)', () => {
    expect(home.map((d) => d.heading)).toEqual([
      'دعاء الخروج من المنزل',
      'دعاء الخروج من المنزل',
      'دعاء دخول المنزل',
    ]);
  });

  it('leaving the house starts with «بِسْمِ اللَّهِ، تَوَكَّلْتُ عَلَى اللَّهِ»', () => {
    expect(home[0].arabic.startsWith('بِسْمِ اللَّهِ، تَوَكَّلْتُ عَلَى اللَّهِ')).toBe(true);
  });

  it('entering the house has «وَلَجْنَا» and «خَرَجْنَا»', () => {
    expect(home[2].arabic).toContain('وَلَجْنَا');
    expect(home[2].arabic).toContain('خَرَجْنَا');
  });

  it("travel has the riding verse and the traveller's du'a, each recited once", () => {
    expect(travel[0].arabic).toContain('سُبْحَانَ الَّذِي سَخَّرَ لَنَا هَذَا');
    expect(travel[1].arabic).toContain('وَعْثَاءِ السَّفَرِ');
    expect(travel.every((d) => d.repeat === 1)).toBe(true);
  });
});

describe('repeat counts from the book', () => {
  const find = (list, start) => list.filter((d) => d.arabic.startsWith(start.normalize('NFC')));

  it('Ayat al-Kursi once, the three Quls three times (morning and evening)', () => {
    for (const list of [morning, evening]) {
      expect(list[0].arabic).toContain('الْحَيُّ الْقَيُّومُ');
      expect(list[0].repeat).toBe(1);
      expect(list[1].arabic).toContain('قُلْ هُوَ اللَّهُ أَحَدٌ');
      expect(list[1].arabic).toContain('بِرَبِّ الْفَلَقِ');
      expect(list[1].arabic).toContain('بِرَبِّ النَّاسِ');
      expect(list[1].repeat).toBe(3);
    }
  });

  it('«سُبْحَانَ اللَّهِ وَبِحَمْدِهِ» 100 times, morning and evening', () => {
    for (const list of [morning, evening]) {
      const matches = list.filter((d) => d.arabic === 'سُبْحَانَ اللَّهِ وَبِحَمْدِهِ'.normalize('NFC'));
      expect(matches).toHaveLength(1);
      expect(matches[0].repeat).toBe(100);
    }
  });

  it('«لا إله إلا الله وحده…» 10 times morning and evening, plus 100 times in the morning only', () => {
    const tahlil = (list) => find(list, 'لاَ إِلَهَ إِلاَّ اللَّهُ').map((d) => d.repeat);
    expect(tahlil(morning)).toEqual([10, 100]);
    expect(tahlil(evening)).toEqual([10]);
  });

  it('«حَسْبِيَ اللَّهُ…» 7 times', () => {
    for (const list of [morning, evening]) {
      expect(find(list, 'حَسْبِيَ اللَّهُ').map((d) => d.repeat)).toEqual([7]);
    }
  });

  it('«أَعُوذُ بِكَلِمَاتِ اللَّهِ التَّامَّاتِ» 3 times, evening only', () => {
    expect(find(morning, 'أَعُوذُ بِكَلِمَاتِ اللَّهِ')).toHaveLength(0);
    expect(find(evening, 'أَعُوذُ بِكَلِمَاتِ اللَّهِ').map((d) => d.repeat)).toEqual([3]);
  });

  it('morning wording in the morning, evening wording in the evening', () => {
    expect(morning.some((d) => d.arabic.includes('أَمْسَيْنَا وَأَمْسَى'.normalize('NFC')))).toBe(false);
    expect(evening.some((d) => d.arabic.includes('أَصْبَحْنَا وَأَصْبَحَ'.normalize('NFC')))).toBe(false);
    expect(evening.some((d) => d.arabic.includes('أَمْسَيْنَا وَأَمْسَى'.normalize('NFC')))).toBe(true);
  });

  it('only 100× adhkar get the counter: three in the morning, two in the evening, none at sleep', () => {
    const hundreds = (list) => list.filter((d) => d.repeat === 100).length;
    expect(hundreds(morning)).toBe(3);
    expect(hundreds(evening)).toBe(2);
    expect(hundreds(sleep)).toBe(0);
  });
});

describe('istikhara', () => {
  it('has the schema { arabic, highlight, source }', () => {
    expect(Object.keys(istikhara).sort()).toEqual(['arabic', 'highlight', 'source']);
    expect(istikhara.highlight).toBe('هَذَا الْأَمْرَ'.normalize('NFC'));
    expect(istikhara.source.trim().length).toBeGreaterThan(0);
  });

  it('starts directly at the du\'a, without the hadith introduction', () => {
    expect(istikhara.arabic.startsWith('اللَّهُمَّ إِنِّي أَسْتَخِيرُكَ بِعِلْمِكَ'.normalize('NFC'))).toBe(true);
    expect(istikhara.arabic).not.toContain('جَابرُ');
    expect(istikhara.arabic).not.toContain('فَلْيَرْكَعْ');
  });

  it('ends with «ثُمَّ أَرْضِنِي بِهِ»', () => {
    expect(istikhara.arabic.endsWith('ثُمَّ أَرْضِنِي بِهِ'.normalize('NFC'))).toBe(true);
  });

  it('contains the highlight phrase exactly twice (the good case and the bad case)', () => {
    expect(count(istikhara.arabic, istikhara.highlight)).toBe(2);
  });
});
